sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartInvest = null;

    $scope.anoSelecionadoInvest = ""; 
    $scope.exibirGraficoInvest = false;

    // Definição das cores
    var coresInvest = {
        barra1: '#a7b9e8', // Investimento
        barra2: '#4b77bf', // RCL
        linha: '#021770'   // Percentual
    };

    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionadoInvest = ano;
        carregarDadosInvestFiltrado(); 
    });

    function carregarDadosInvestFiltrado() {
        var filtros = {
            ano: $scope.anoSelecionadoInvest 
        };

        $scope.server.get(filtros).then(function(response) {
            var dados = response.data.dadosGraficoInvest || [];

            // --- MUDANÇA AQUI: VERIFICAÇÃO SEGURA ---
            verificarBibliotecaChart(function() {
                montarGraficoInvest(dados);
            });
        });
    }

    /**
     * --- NOVA FUNÇÃO DE SEGURANÇA ---
     * Garante que o Chart.js está carregado antes de tentar usar.
     */
    function verificarBibliotecaChart(callbackSucesso) {
        if (typeof Chart !== 'undefined') {
            callbackSucesso();
        } else {
            // Se ainda não carregou, espera 500ms e tenta de novo
            $timeout(function() {
                verificarBibliotecaChart(callbackSucesso);
            }, 500);
        }
    }

    carregarDadosInvestFiltrado();

    function montarGraficoInvest(listaDados) {

        // 1. Preparação dos dados
        var anosPresentes = [];
        listaDados.forEach(function(item) {
            if (anosPresentes.indexOf(item.ano) === -1) {
                anosPresentes.push(item.ano);
            }
        });

        anosPresentes.sort(function(a, b) {
            return parseInt(a) - parseInt(b);
        });

        // Se não tiver dados, destrói e esconde
        if (anosPresentes.length === 0) {
            if (chartInvest) {
                chartInvest.destroy();
                chartInvest = null;
            }
            $scope.exibirGraficoInvest = false;
            $scope.$applyAsync(); // Atualiza a view
            return;
        }

        $scope.exibirGraficoInvest = true;
        $scope.$applyAsync(); // Garante que a DIV apareça antes de buscar o ID


        function parseValue(val) {
            if (!val) return null;
            // Remove pontos de milhar e troca vírgula por ponto
            var cleanVal = val.toString().replace(/\./g, '').replace(',', '.');
            return parseFloat(cleanVal);
        }

        function parsePercent(val) {
                if (!val) return null;
                var cleanVal = val.toString().replace(',', '.');
                return parseFloat(cleanVal);
        }

        // Mapeamento dos Dados
        var dadosInvest1 = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseValue(item.investimento) : 0;
        });

        var dadosInvest2 = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseValue(item.investimento2) : 0;
        });

        var dadosPercentual = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parsePercent(item.percentual) : 0;
        });

        // 2. Configuração dos Datasets
        var datasets = [
            {
                label: 'Investimento Empenhado',
                data: dadosInvest1,
                backgroundColor: coresInvest.barra1,
                borderColor: coresInvest.barra1,
                borderWidth: 1,
                order: 2, 
                yAxisID: 'y'
            },
            {
                label: 'Receita Corrente Líquida',
                data: dadosInvest2,
                backgroundColor: coresInvest.barra2,
                borderColor: coresInvest.barra2,
                borderWidth: 1,
                order: 3, 
                yAxisID: 'y'
            },
            {
                type: 'line',
                label: 'Percentual da RCL',
                data: dadosPercentual,
                borderColor: coresInvest.linha,
                backgroundColor: coresInvest.linha,
                borderWidth: 3,
                pointStyle: 'circle',
                pointRadius: 4,
                order: 1, 
                yAxisID: 'y1',
                datalabels: {
                    align: 'top',
                    anchor: 'end',
                    formatter: function(value) {
                            return value.toLocaleString('pt-BR', { minimumFractionDigits: 2 }) + '%';
                    }
                }
            }
        ];

        // --- SEGURANÇA ADICIONAL ---
        // Verifica se o elemento existe no HTML antes de tentar desenhar
        var element = document.getElementById('graficoInvestimento');
        if (!element) return; // Se o elemento não existe, para aqui

        var ctx = element.getContext('2d');

        // Renderização do Gráfico
        if (chartInvest) {
            chartInvest.data.labels = anosPresentes;
            chartInvest.data.datasets = datasets;
            chartInvest.update();

        } else {

            chartInvest = new Chart(ctx, {
                type: 'bar', 
                data: {
                    labels: anosPresentes,
                    datasets: datasets
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    interaction: {
                        mode: 'index',
                        intersect: false,
                    },
                    scales: {
                        x: {
                            display: true,
                            grid: { display: false },
                            ticks: {
                                color: '#0E2B69',
                                font: {
                                    size: 14,
                                    family: 'Roboto Flex, sans-serif',
                                    weight: 600
                                }
                            }
                        },
                        y: {
                            type: 'linear',
                            display: true,
                            position: 'left',
                            title: { display: true, text: 'Valores (R$)' },
                            ticks: {
                                color: '#0E2B69',
                                callback: function(value) {
                                    return 'R$ ' + value.toLocaleString('pt-BR', {
                                        maximumFractionDigits: 0
                                    });
                                }
                            }
                        },
                        y1: {
                            type: 'linear',
                            display: true,
                            position: 'right',
                            grid: {
                                drawOnChartArea: false 
                            },
                            title: { display: true, text: 'Percentual (%)' },
                            ticks: {
                                color: coresInvest.linha,
                                callback: function(value) {
                                    return value + '%';
                                }
                            }
                        }
                    },
                    plugins: {
                        legend: {
                            display: true,
                            position: 'top',
                            labels: { usePointStyle: true }
                        },
                        tooltip: {
                            enabled: true,
                            callbacks: {
                                label: function(context) {
                                    var label = context.dataset.label || '';
                                    var value = context.raw;
                                    if (context.dataset.type === 'line' || context.dataset.yAxisID === 'y1') {
                                        return label + ': ' + value.toLocaleString('pt-BR', {minimumFractionDigits: 2}) + '%';
                                    } else {
                                        return label + ': R$ ' + value.toLocaleString('pt-BR', {minimumFractionDigits: 2});
                                    }
                                }
                            }
                        },
                        datalabels: {
                            display: function(context) {
                                return context.dataset.type === 'line'; 
                            },
                            color: '#000',
                            font: { weight: 'bold' }
                        }
                    }
                }
            });
        }
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

.titleInvest{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    data.dadosGraficoInvest = [];

    // Pega o ano enviado
    var anoFiltro = input.ano || "";

    // Consulta na nova tabela solicitada
    var gr = new GlideRecord('x_sded9_portal_t_0_investimento');

    // Aplica filtro de ano se houver
    if (anoFiltro && anoFiltro !== "") {
        gr.addQuery('u_ano', anoFiltro);
    }

    gr.orderBy('u_ano');
    gr.query();

    var lista = [];
    while (gr.next()) {
        // Atenção: Você solicitou "investimento_empenhado" para as duas barras.
        // Se a segunda barra deveria ser "Receita Corrente Líquida" (RCL),
        // altere a propriedade 'investimento2' abaixo para pegar o campo correto.

        lista.push({
            ano: gr.getValue('u_ano').toString(),
            investimento: gr.getValue('investimento_empenhado'),  // Barra 1
            investimento2: gr.getValue('receita_corrente_liquida'), // Barra 2 (Repetido conforme pedido)
            percentual: gr.getValue('percentual_da_rcl_investimento_empenhado') // Linha
        });
    }

    data.dadosGraficoInvest = lista;
})();
